//! A plugin built against `jellyfesh:plugin@1.1.0` exactly as v0.0.6
//! released it (`wit/` is a frozen copy, never to be edited), without the
//! SDK, which now builds for 1.2. Searching echoes the query and hashes it
//! with the 1.1 `crypto` import; the `remote` export (new in 1.1) lists one
//! invented device. A passing test shows a 1.2 host links 1.1 imports and
//! finds 1.1 exports, `remote` included.

#[allow(unsafe_code, reason = "canonical ABI glue generated by wit-bindgen")]
#[allow(missing_debug_implementations, reason = "generated code")]
mod bindings {
    wit_bindgen::generate!({
        world: "remote-source",
        path: "wit",
    });
}

use bindings::exports::jellyfesh::plugin::{
    artwork, auth, catalog, lyrics, meta, playback, recommendations, remote,
};
use bindings::jellyfesh::plugin::crypto::{HashAlgorithm, digest};
use bindings::jellyfesh::plugin::types::{ImageRef, Item, ItemKind, ItemPage, PageRequest, PluginError};

struct Compat;

impl meta::Guest for Compat {
    fn capabilities() -> Vec<meta::Capability> {
        vec![meta::Capability::Search]
    }
    fn settings_changed(_settings: String) -> Result<(), PluginError> {
        Ok(())
    }
}

impl auth::Guest for Compat {
    fn begin(_flow: auth::Flow) -> Result<auth::FlowStep, PluginError> {
        Err(PluginError::Unsupported)
    }
    fn poll(_flow: auth::Flow) -> Result<auth::FlowStep, PluginError> {
        Err(PluginError::Unsupported)
    }
    fn submit(_flow: auth::Flow, _fields: Vec<auth::FieldValue>) -> Result<auth::FlowStep, PluginError> {
        Err(PluginError::Unsupported)
    }
    fn logout() -> Result<(), PluginError> {
        Ok(())
    }
}

impl catalog::Guest for Compat {
    fn search(
        query: String,
        _filters: catalog::SearchFilters,
        _page: PageRequest,
    ) -> Result<ItemPage, PluginError> {
        let hash = digest(HashAlgorithm::Sha256, query.as_bytes())
            .map_err(|e| PluginError::Internal(format!("crypto: {e:?}")))?;
        let hex: String = hash.iter().map(|b| format!("{b:02x}")).collect();
        Ok(ItemPage {
            items: vec![Item {
                id: "compat-11".into(),
                kind: ItemKind::Track,
                title: format!("1.1 says {query}"),
                artist: Some(hex),
                album: None,
                album_id: None,
                artist_id: None,
                duration_ms: Some(1000),
                track_number: None,
                disc_number: None,
                year: None,
                child_count: None,
                isrc: None,
                artwork: None,
                explicit: false,
                playable: true,
                unplayable: None,
            }],
            next: None,
            total: Some(1),
        })
    }
    fn browse(_node: Option<Item>, _page: PageRequest) -> Result<ItemPage, PluginError> {
        Err(PluginError::Unsupported)
    }
}

impl playback::Guest for Compat {
    fn resolve_stream(_item: Item, _quality: playback::Quality) -> Result<playback::StreamInfo, PluginError> {
        Err(PluginError::Unsupported)
    }
}

impl lyrics::Guest for Compat {
    fn lyrics(_item: Item) -> Result<Option<lyrics::LyricPayload>, PluginError> {
        Err(PluginError::Unsupported)
    }
}

impl artwork::Guest for Compat {
    fn artwork(_item: Item, _size: u32) -> Result<Option<ImageRef>, PluginError> {
        Err(PluginError::Unsupported)
    }
}

impl recommendations::Guest for Compat {
    fn for_item(_item: Item, _page: PageRequest) -> Result<ItemPage, PluginError> {
        Err(PluginError::Unsupported)
    }
    fn for_user(_page: PageRequest) -> Result<ItemPage, PluginError> {
        Err(PluginError::Unsupported)
    }
}

impl remote::Guest for Compat {
    fn devices() -> Result<Vec<remote::Device>, PluginError> {
        Ok(vec![remote::Device {
            id: "compat-speaker".into(),
            name: "Compat Speaker".into(),
            kind: remote::DeviceKind::Speaker,
            active: false,
            supports_volume: false,
            volume_percent: None,
        }])
    }
    fn state() -> Result<Option<remote::PlaybackState>, PluginError> {
        Ok(None)
    }
    fn play(
        _device: Option<String>,
        _context: Option<Item>,
        _tracks: Vec<Item>,
        _start: u32,
    ) -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn resume() -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn pause() -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn next() -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn previous() -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn seek(_position_ms: u32) -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn set_volume(_percent: u32) -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn set_shuffle(_on: bool) -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn set_repeat(_mode: remote::Repeat) -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
    fn transfer(_device: String, _play: bool) -> Result<(), PluginError> {
        Err(PluginError::Unsupported)
    }
}

#[cfg(target_arch = "wasm32")]
#[allow(unsafe_code, reason = "canonical ABI glue generated by wit-bindgen")]
const _: () = {
    bindings::export!(Compat with_types_in bindings);
};
